package cli

import (
	"os"
	"path/filepath"
	"testing"
)

// Security review: impr removes or replaces only a completion file it wrote
// itself (the "generated by impr completion" line), never someone else's file
// at the same path, and never through a symbolic link.
func TestCompletionTouchesOnlyItsOwnFiles(t *testing.T) {
	h := newHarness(t)
	h.home = t.TempDir()
	fish := filepath.Join(h.home, ".config", "fish", "completions", "impr.fish")
	if err := os.MkdirAll(filepath.Dir(fish), 0o750); err != nil {
		t.Fatal(err)
	}
	mine := []byte("# my own impr completions\ncomplete -c impr -a hand-written\n")
	if err := os.WriteFile(fish, mine, 0o600); err != nil {
		t.Fatal(err)
	}
	h.exits(1, "completion", "uninstall", "fish")
	h.exits(1, "completion", "install", "fish")
	if b, err := os.ReadFile(fish); err != nil || string(b) != string(mine) {
		t.Fatalf("a file impr did not write was changed: %q %v", b, err)
	}
	// A link at the path is left alone too.
	target := filepath.Join(t.TempDir(), "elsewhere")
	if err := os.WriteFile(target, []byte("# impr completion for fish (generated by impr completion fish)\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(fish); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(target, fish); err != nil {
		t.Fatal(err)
	}
	h.exits(1, "completion", "uninstall", "fish")
	if _, err := os.Lstat(fish); err != nil {
		t.Fatalf("the link was removed: %v", err)
	}
	// With "all", the foreign file stops the run before bash is written.
	h.exits(1, "completion", "install", "all")
	if _, err := os.Stat(filepath.Join(h.home, ".local", "share", "bash-completion", "completions", "impr")); !os.IsNotExist(err) {
		t.Fatalf("install all wrote bash before refusing fish: %v", err)
	}
	// impr's own file installs, reinstalls and uninstalls as before.
	if err := os.Remove(fish); err != nil {
		t.Fatal(err)
	}
	h.ok("completion", "install", "fish")
	h.ok("completion", "install", "fish")
	h.ok("completion", "uninstall", "fish")
	if _, err := os.Lstat(fish); !os.IsNotExist(err) {
		t.Fatalf("impr's own file was not removed: %v", err)
	}
}
